"""How fast is the bundled reference-style approach (networkx network simplex)?"""
import sys, time
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/deps'); sys.path.insert(0,'/workspace/tests')
import networkx as nx
from plan_worst import build
from common import validate
from planning import solve

def nx_solve(ctx, active, job):
    requests=ctx['requests']; offers=ctx['offers']; leases=ctx['leases']
    rq=ctx['request_quotas']; oq=ctx['offer_quotas']
    G=nx.DiGraph()
    S='S'; T='T'
    for oid,o in offers.items():
        if o['capacity']<=0: continue
        net=o['network']; lo=int(net.network_address); hi=int(net.broadcast_address)
        for rid in o['requests']:
            r=requests[rid]
            if not active.get(rid): continue
            if r['service']!=o['service']: continue
            if r['at']>o['time'] or o['time']>=leases[r['lease']]['end']: continue
            if not (lo<=r['address']<=hi): continue
            G.add_edge(('r',rid),('o',oid),capacity=1,weight=o['cost'])
    for rid,r in requests.items():
        if G.has_node(('r',rid)):
            G.add_edge(('rq',r['group']),('r',rid),capacity=1,weight=0)
    for oid,o in offers.items():
        if G.has_node(('o',oid)):
            G.add_edge(('o',oid),('oq',o['group']),capacity=o['capacity'],weight=0)
    for name,node in rq.items():
        if node['parent'] is None: G.add_edge(S,('rq',name),capacity=node['capacity'],weight=0)
        else: G.add_edge(('rq',node['parent']),('rq',name),capacity=node['capacity'],weight=0)
    for name,node in oq.items():
        if node['parent'] is None: G.add_edge(('oq',name),T,capacity=node['capacity'],weight=0)
        else: G.add_edge(('oq',name),('oq',node['parent']),capacity=node['capacity'],weight=0)
    if not G.has_node(S) or not G.has_node(T): return 0,0
    flow=nx.max_flow_min_cost(G,S,T,capacity='capacity',weight='weight')
    total=0; cost=0
    for u,v,d in G.edges(data=True):
        if u[0]=='r' and v[0]=='o':
            f=d.get('flow',0)
            if f: total+=f; cost+=f*d['weight']
    return total,cost

for nreq,noff,per,qcap in ((100,200,20,50),(200,400,25,100),(400,800,30,200)):
    job=build(nreq,noff,per,quota_cap=qcap)
    ctx=validate(job); active={r['id']:True for r in job['requests']}
    t=time.time(); mine=solve(ctx,active); t1=time.time()-t
    t=time.time(); got=nx_solve(ctx,active,job); t2=time.time()-t
    print('nreq=%d noff=%d qcap=%d mine=%d/%d %.2fs   networkx=%s %.2fs' % (
        nreq,noff,qcap,mine['resolved'],mine['cost'],t1,got,t2))
PYEOF
